package com.ecommerce.auth; import com.ecommerce.common.ApiException; import com.ecommerce.user.*; import jakarta.validation.constraints.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { public record Register(@NotBlank String name,@Email @NotBlank String email,@Size(min=8,max=100) String password,User.Role role){} public record Login(@Email @NotBlank String email,@NotBlank String password){} private final UserRepository repo; private final PasswordEncoder enc; private final JwtService jwt; public AuthController(UserRepository r,PasswordEncoder e,JwtService j){repo=r;enc=e;jwt=j;} @PostMapping("/register") public Map<String,Object> register(@RequestBody @jakarta.validation.Valid Register x){if(repo.existsByEmailIgnoreCase(x.email()))throw new ApiException("Email already registered");User u=new User();u.setName(x.name());u.setEmail(x.email().toLowerCase(Locale.ROOT));u.setPasswordHash(enc.encode(x.password()));u.setRole(x.role()==null?User.Role.CUSTOMER:x.role());if(u.getRole()==User.Role.ADMIN)throw new ApiException("Admin registration is disabled");repo.save(u);return Map.of("id",u.getId(),"email",u.getEmail(),"role",u.getRole());} @PostMapping("/login") public Map<String,Object> login(@RequestBody @jakarta.validation.Valid Login x){User u=repo.findByEmailIgnoreCase(x.email()).orElseThrow(()->new ApiException("Invalid credentials"));if(!enc.matches(x.password(),u.getPasswordHash())||u.getStatus()!=User.Status.ACTIVE)throw new ApiException("Invalid credentials");return Map.of("accessToken",jwt.token(u.getEmail(),u.getRole().name()),"refreshToken",jwt.refresh(u.getEmail(),u.getRole().name()),"tokenType","Bearer");} }
